contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newImpl) public {
        require(newImpl != address(0));

        bool reverted;
        c.updateRoundImplementation(payable(newImpl)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || c.roundImplementation() == newImpl);
    }
}

