pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(address newImpl) internal {
        vm.assume(newImpl != address(0));
        bool reverted;
        try c.updateRoundImplementation(payable(newImpl)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || c.roundImplementation() == newImpl);
    }

    function testFuzz_run(address newImpl) public {
        vm.assume(newImpl.code.length == 0 && uint160(newImpl) > 0xffff && newImpl != address(this) && newImpl != address(c) && newImpl != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newImpl != 0x000000000000000000636F6e736F6c652e6c6f67 && newImpl != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newImpl != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newImpl);
    }

    receive() external payable {}
}
